require_once __DIR__.'/includes/functions.php';require_login();require_once __DIR__.'/config/database.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT s.*,c.full_name AS customer_name,c.phone,c.email,u.full_name AS cashier FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.user_id WHERE s.id=?');$q->execute([$id]);$sale=$q->fetch();if(!$sale){flash('danger','Sale record was not found.');redirect('sales.php');}$q=$pdo->prepare('SELECT si.*,p.name,p.sku FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?');$q->execute([$id]);$items=$q->fetchAll();$pageTitle='Sale Invoice';require __DIR__.'/includes/header.php';
?>
